import React from "react";
import Navbar from "../components/navbar"; // Top navigation bar
import Footer from "../components/footer"; // Footer
import SupervisorSidebar from "../components/SupervisorSidebar"; // Sidebar
import "./SupervisorDashboard.css";

const SupervisorDashboard = () => {
  const features = [
    { id: 1, title: "Provide Feedback", description: "Review and provide feedback on student submissions.", icon: "fas fa-comment-dots" },
    { id: 2, title: "Track Progress", description: "Monitor and evaluate the progress of assigned teams.", icon: "fas fa-chart-line" },
    { id: 3, title: "Schedule Meetings", description: "Organize and manage meetings with students or teams.", icon: "fas fa-calendar" },
    { id: 4, title: "Generate Reports", description: "Create detailed reports for projects.", icon: "fas fa-file-alt" },
    { id: 5, title: "Access Communication Tools", description: "Use tools to communicate effectively with teams.", icon: "fas fa-tools" },
    { id: 6, title: "Search Documents", description: "Easily find project-related documents.", icon: "fas fa-search" },
  ];

  return (
    <div className="dashboard-container">
      {/* Navbar */}
      <Navbar />

      <div className="dashboard-layout">
        {/* Sidebar */}
        <SupervisorSidebar />

        {/* Main Content */}
        <main className="dashboard-main">
          <div className="hero-section">
            <h1>Welcome, Supervisor!</h1>
            <p>Manage projects, track progress, and provide valuable feedback.</p>
          </div>

          <div className="dashboard-content">
            <div className="dashboard-section">
              <h2>Features</h2>
              <div className="card-grid">
                {features.map((feature) => (
                  <div key={feature.id} className="dashboard-card">
                    <i className={feature.icon}></i>
                    <h3>{feature.title}</h3>
                    <p>{feature.description}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </main>
      </div>

      {/* Footer */}
      <Footer />
    </div>
  );
};

export default SupervisorDashboard;
